def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    WC = 1
    water = sorted(zip(*np.where(g == WC)))
    n = len(water)
    if n == 0:
        emit(g, "No water present; nothing changes.")
        return g
    src = water[0]
    for (y, x) in water:
        g[y, x] = 0
    emit(g, f"Remove all {n} water cells (colour 1); they are re-poured one at a time from {tuple(int(v) for v in src)}.")

    def open_below(y, x):
        return y + 1 < H and g[y + 1, x] == 0

    for k in range(n):
        y, x = int(src[0]), int(src[1])
        if g[y, x] != 0:
            break
        for _ in range(10000):
            if open_below(y, x):
                y += 1
                continue
            best = None
            for d in (-1, 1):
                cx, dist = x, 0
                while True:
                    cx += d
                    dist += 1
                    if cx < 0 or cx >= W or g[y, cx] != 0:
                        break
                    if open_below(y, cx):
                        if best is None or dist < best[0]:
                            best = (dist, cx)
                        break
            if best is None:
                break
            x = best[1]
        g[y, x] = WC
        emit(g, f"Pour water cell {k+1}/{n}: it falls and flows to the nearest drop, settling at ({y},{x}).")
    emit(g, "All water has settled into the containers.")
    return g
